import{bQ as r,aL as o,u as e,G as a}from"./chunks/framework.D06dwy5q.js";const n="/kb/assets/gpt-image-2.5-sunburst_a_%E8%BE%93%E5%85%A5%E4%B8%8A%E6%96%87%EF%BC%9A%E3%80%90%E5%BA%8A%E5%89%8D%E6%98%8E%E6%9C%88%E5%85%89%E3%80%91_.7LPpLgZL.png",s="/kb/assets/gpt-image-2.5-sunburst_a_%E4%BA%BA%E7%B1%BB%E8%AF%AF%E8%A7%A3%EF%BC%9AAI___%E5%B7%A8%E5%9E%8B%E7%99%BE%E5%BA%A6%E7%BD%91%E7%9B%98%EF%BC%88%E9%81%87%E5%88%B0%E9%97%AE.AoR64l_N.png",b=JSON.parse('{"title":"第 02 篇｜大模型的底层直觉：为什么它会“像天才一样创作，像智障一样胡扯”？","description":"","frontmatter":{},"headers":[],"relativePath":"AI-Native 普通人零代码实战指南/第 02 篇｜大模型的底层直觉：为什么它会“像天才一样创作，像智障一样胡扯”？.md","filePath":"AI-Native 普通人零代码实战指南/第 02 篇｜大模型的底层直觉：为什么它会“像天才一样创作，像智障一样胡扯”？.md","lastUpdated":null}'),l={name:"AI-Native 普通人零代码实战指南/第 02 篇｜大模型的底层直觉：为什么它会“像天才一样创作，像智障一样胡扯”？.md"};function i(g,t,d,_,p,h){return o(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="第-02-篇-大模型的底层直觉-为什么它会-像天才一样创作-像智障一样胡扯" tabindex="-1">第 02 篇｜大模型的底层直觉：为什么它会“像天才一样创作，像智障一样胡扯”？ <a class="header-anchor" href="#第-02-篇-大模型的底层直觉-为什么它会-像天才一样创作-像智障一样胡扯" aria-label="Permalink to &quot;第 02 篇｜大模型的底层直觉：为什么它会“像天才一样创作，像智障一样胡扯”？&quot;">​</a></h1><blockquote><p><strong>导读</strong>：<br> 刚接触 AI 的人，往往在两个极端之间反复横跳：今天看到它秒写代码，惊呼“人类要失业了”；明天看它坚称“林黛玉倒拔垂杨柳”，又嘲笑“这玩意儿就是人工智障”。<br> 为什么同一个模型，能写出惊艳全场的文案，却又会一本正经地胡说八道？<br> 这一篇，我们撕开 AI 华丽的外衣，带你看透它的底层脑回路。读懂了它的弱点，你才不会被它带进沟里，才能真正成为驾驭它的总指挥。</p></blockquote><hr><h3 id="一、-两个让你怀疑人生的经典-翻车-场景" tabindex="-1">一、 两个让你怀疑人生的经典“翻车”场景 <a class="header-anchor" href="#一、-两个让你怀疑人生的经典-翻车-场景" aria-label="Permalink to &quot;一、 两个让你怀疑人生的经典“翻车”场景&quot;">​</a></h3><p>只要你用过一段时间 AI，十有八九遭遇过这两种精神暴击：</p><p><strong>场景一：一本正经的“学术胡诌”</strong><br> 你让 AI 帮你调研：“请列出 2024 年关于某技术的前三篇经典论文和作者。”<br> AI 毫不犹豫，啪啪列出三篇：英文标题高大上、作者是常青藤教授、期刊名精准匹配。你兴奋地去 Google 搜索，结果<strong>查无此文</strong>，连教授最近三年都没写过这方向的论文——这三篇论文，完全是 AI <strong>凭空捏造</strong>出来的。</p><p><strong>场景二：写代码时的“幽灵函数”</strong><br> 你让 AI 写个小功能：“把用户上传的 Excel 转成 PDF。”<br> AI 潇洒地给出一行核心代码：<code>excelTool.magicExportToPdf()</code>。你一跑，终端立刻甩脸报错：“未定义此函数”。你质问它，它还非常客气地道歉：“对不起，是我记错了，请使用 <code>excelTool.convertDirectly()</code>”——好家伙，又是一个它现编出来的假函数！</p><p>很多人遇到这种破事，第一反应是：“AI 在骗我！这东西根本不能用于严肃工作。”</p><p><strong>其实，AI 从来没有骗你，因为“欺骗”需要主观恶意。</strong><br><strong>比被骗更恐怖的真相是：在 AI 的世界里，根本就没有“真”和“假”这两个概念。</strong></p><hr><h3 id="二、-揭秘黑盒-它不是真理机器-是-超级概率接龙大师" tabindex="-1">二、 揭秘黑盒：它不是真理机器，是“超级概率接龙大师” <a class="header-anchor" href="#二、-揭秘黑盒-它不是真理机器-是-超级概率接龙大师" aria-label="Permalink to &quot;二、 揭秘黑盒：它不是真理机器，是“超级概率接龙大师”&quot;">​</a></h3><p>要理解 AI 的一切神迹与荒唐，你只需要记住一句话：<br><strong>大语言模型（LLM）的本质，是一个基于概率的“文字接龙游戏机”（Next-Token Prediction）。</strong></p><p><img src="'+n+'" alt="gpt-image-2.5-sunburst_a_输入上文：【床前明月光】_"></p><p>不管你给 AI 抛出多宏大、多严肃的问题，它在大脑内部只做一件事：<br><strong>“根据前面已经出现的这一堆字，计算出后面接哪个字最合乎常理？”</strong></p><p>理解这一点，至关重要：</p><ul><li><strong>传统计算器的工作方式</strong>：输入 <code>1 + 1</code>，调取固定算力，严格输出 <code>2</code>。</li><li><strong>大模型的工作方式</strong>：阅读了人类几十万亿字的互联网网页后，它发现当出现 <code>1 + 1 = </code> 时，后面跟着 <code>2</code> 的概率高达 99.999%，于是它吐出了 <code>2</code>。</li></ul><p>这就解释了为什么它会胡说八道：<br><strong>AI 追求的终极目标，从来不是“客观真理”，而是“听起来合理（Plausible）”。</strong></p><p>当它编造不存在的论文或代码函数时，它的大脑思维是：“在学术论文这种语境下，作者的名字像个学者、文章名字包含几个热门词汇，从语法和结构上看简直太顺畅了！”<br> 它满意地把接龙继续了下去，压根不在乎现实世界里到底有没有这个人。</p><hr><h3 id="三、-幻觉-hallucination-从何而来" tabindex="-1">三、 幻觉（Hallucination）从何而来？ <a class="header-anchor" href="#三、-幻觉-hallucination-从何而来" aria-label="Permalink to &quot;三、 幻觉（Hallucination）从何而来？&quot;">​</a></h3><p>业内管 AI 的这种瞎编叫**“幻觉”**。很多人问：“既然 AI 这么强大，科学家为什么不在它的肚子里塞一本《新华字典》或者客观事实数据库，不准它编造呢？”</p><p>这就是关于大模型的第二个巨大认知误区：<br><strong>AI 的肚子里，根本没有存储任何一篇文章或代码的原文。</strong></p><p><img src="'+s+'" alt="gpt-image-2.5-sunburst_a_人类误解：AI_=_巨型百度网盘（遇到问"></p><p>科学家把整个互联网的知识（维基百科、GitHub 代码、Reddit 论坛、电子书）塞进 AI 训练时，并不是把字存下来，而是通过数学计算，把几百 TB 的文字<strong>极度压缩</strong>成几百亿、几千亿个参数权重。</p><p>这就像一个记忆力超群的高中生，考前把三年教材疯狂通读了一遍，进考场时教材全被没收，他只能**凭脑子里的模糊印象（权重）**来答题：</p><ol><li><strong>遇到高频知识</strong>（如“李白是哪朝人”、“怎么写 Python 冒泡排序”）：这在训练集里被翻来覆去强化过上亿次，他的印象无比深刻，答对率 99.9%。</li><li><strong>遇到冷门领域 / 极细技术细节</strong>：他的脑子里只有点零碎的印象。但考卷不能空着（系统要求接龙继续），在概率指引下，他的大脑自动开始<strong>脑补、联想、拼凑</strong>。</li></ol><p><strong>划重点：AI 越不懂的东西，它越喜欢用最笃定的语气去编造。</strong><br> 因为在它的概率字典里，“我不知道”往往不是最顺畅的接龙选项，顺着你的问题编一段严谨的假话，概率分数反而最高。</p><hr><h3 id="四、-上下文窗口-context-window-为什么它聊着聊着就变笨、甚至失忆" tabindex="-1">四、 上下文窗口（Context Window）：为什么它聊着聊着就变笨、甚至失忆？ <a class="header-anchor" href="#四、-上下文窗口-context-window-为什么它聊着聊着就变笨、甚至失忆" aria-label="Permalink to &quot;四、 上下文窗口（Context Window）：为什么它聊着聊着就变笨、甚至失忆？&quot;">​</a></h3><p>做实际项目时，普通人最常遇到的另一个崩溃体验是：<br><em>“我和 AI 聊得好好的，帮我写了几千行代码，怎么聊到后面，它突然把我前面定好的规则全忘了？甚至连刚才写的变量名都不认得，越改越烂？”</em></p><p>这里涉及到一个核心物理限制：<strong>上下文窗口（Context Window）</strong>。</p><h4 id="_1-办公桌比喻" tabindex="-1">1. 办公桌比喻 <a class="header-anchor" href="#_1-办公桌比喻" aria-label="Permalink to &quot;1. 办公桌比喻&quot;">​</a></h4><p>你可以把 AI 当作一个绝顶聪明、但患有“短期失忆症”的打工人：</p><ul><li>它的<strong>上下文窗口</strong>，就是它工位上的<strong>办公桌桌面大小</strong>。</li><li>只要你在窗口里输入文字，文字就会铺在桌面上。</li><li>桌面不是无限大的（哪怕现在有宣称几十万、上百万 Token 容量的模型，桌子变大了，但注意力依然有限）。</li></ul><p>![gpt-image-2.5-sunburst_a_┌─────────────────── (1)](./assets/gpt-image-2.5-sunburst_a_┌─────────────────── (1).png)</p><h4 id="_2-变笨-的两个致命诱因" tabindex="-1">2. “变笨”的两个致命诱因 <a class="header-anchor" href="#_2-变笨-的两个致命诱因" aria-label="Permalink to &quot;2. “变笨”的两个致命诱因&quot;">​</a></h4><ul><li><strong>信息被挤出窗口（Truncation）</strong>：当对话历史太长，超过了模型处理的极限，最前面的记忆就被无情地推下了桌子。它不是故意违背你的设计，它是真的“物理性遗忘”了。</li><li><strong>注意力稀释与污染（Lost in the Middle）</strong>：就算桌子足够大，但如果桌上堆满了 20 轮失败的报错日志、垃圾代码片段，AI 在接龙时，注意力会被这堆“错误信息”严重干扰。它会产生思维定势，在错误的基础上越陷越深。</li></ul><h4 id="_3-为什么关掉网页就-形同陌路" tabindex="-1">3. 为什么关掉网页就“形同陌路”？ <a class="header-anchor" href="#_3-为什么关掉网页就-形同陌路" aria-label="Permalink to &quot;3. 为什么关掉网页就“形同陌路”？&quot;">​</a></h4><p>大模型的每一次推理都是<strong>无状态的（Stateless）</strong>。它不会在后台偷偷记住你。你点击网页上的“新建会话（New Chat）”，相当于把桌上的草稿纸一把全扫进了垃圾桶。下一次你向它问好，它面对的是一张崭新的空桌子。</p><hr><h3 id="五、-认知重塑-如何让-概率接龙怪-乖乖说真话" tabindex="-1">五、 认知重塑：如何让“概率接龙怪”乖乖说真话？ <a class="header-anchor" href="#五、-认知重塑-如何让-概率接龙怪-乖乖说真话" aria-label="Permalink to &quot;五、 认知重塑：如何让“概率接龙怪”乖乖说真话？&quot;">​</a></h3><p>知道了 AI 的底层缺陷，我们不是要放弃它，而是要像老练的项目总监一样，<strong>在管理上建立防范机制</strong>。</p><p>掌握以下三条法则，你就能瞬间甩开 90% 的普通用户：</p><table tabindex="0"><thead><tr><th style="text-align:left;">面对的问题</th><th style="text-align:left;">错误姿势（新手思维）</th><th style="text-align:left;">正确姿势（AI-Native 架构思维）</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>容易出现幻觉</strong></td><td style="text-align:left;">考它闭卷考试：“你给我凭空写一个冷门库的代码。”</td><td style="text-align:left;"><strong>开卷考试（提供参考源）</strong>：“这是这个库的官方文档片段（粘贴或接入），请严格基于文档写代码。”</td></tr><tr><td style="text-align:left;"><strong>喜欢不懂装懂</strong></td><td style="text-align:left;">任由它随意发挥。</td><td style="text-align:left;"><strong>施加负面约束</strong>：“如果在文档中找不到依据，请直接回答‘无法确认’，严禁自己捏造任何参数。”</td></tr><tr><td style="text-align:left;"><strong>聊太长越改越烂</strong></td><td style="text-align:left;">在一个对话框里死磕 3 天，发了几百条消息求它修 Bug。</td><td style="text-align:left;"><strong>果断断舍离（开新局）</strong>：提炼当前真正有用的上下文，换个干净的新窗口，只喂核心代码重新发问。</td></tr></tbody></table><p><strong>一句话总结它的心智模型：</strong><br> 永远不要把大模型当成算无遗策的神；把它当成一个<strong>喝了三杯浓缩咖啡、读过人类大部分网页、热情洋溢但随时可能吹牛的超级实习生</strong>。</p><p>你的价值，就是给他提供准确的参考资料，并在关键节点进行核查把关。</p><hr><h3 id="📝-结语与本篇自查" tabindex="-1">📝 结语与本篇自查 <a class="header-anchor" href="#📝-结语与本篇自查" aria-label="Permalink to &quot;📝 结语与本篇自查&quot;">​</a></h3><p>做个小测试，检验你是否已经摸透了大模型的脾气：</p><ol><li><strong>AI 吐出的代码里出现了一个根本不存在的报错函数，是它故意在骗你吗？</strong><br><em>(不是。它只是基于概率接龙，算出了一个最像真实代码的词，它没有真理概念。)</em></li><li><strong>为什么把需求文档直接粘贴给 AI，比让它自己凭空想，生成的质量要高得多？</strong><br><em>(因为你给它提供了桌上的强约束锚点，把难度极高的“闭卷凭空联想”变成了“开卷归纳提取”，极大压制了幻觉。)</em></li><li><strong>一个会话聊了很久，AI 突然开始重复犯同样的低级错误，最明智的做法是什么？</strong><br><em>(立刻停止在这个会话纠缠。整理当前正确的代码基线，新建一个干净的会话重新开始。)</em></li></ol><hr><p><strong>下一篇预告</strong>：<br> 既然 AI 有这些先天残疾——看不见实时变动、不联网就不知道最新技术、记忆只有一张桌子大……那我们怎么在实际项目中给它“外挂义肢”？<br> 在下一篇《<strong>给 AI 装上器官：破解多模态、实时性与短期记忆硬伤</strong>》中，我们将进入硬核实战认知，教你如何用截图、RAG 和本地规则文件，把这个有残缺的实习生打造成全副武装的特种兵。</p>',52)])])}const u=r(l,[["render",i]]);export{b as __pageData,u as default};
